/**
* @brief  This function handles UART interrupt request.
* @param  huart  Pointer to a UART_HandleTypeDef structure that contains
*                the configuration information for the specified UART module.
* @retval None
*/
void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* In emulation environment, simulate UART interrupt handling */

  /* Check if we're in receive mode and should receive data */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Simulate receiving data from stdin */
    int bytes_read = HAL_BE_In(huart->pRxBuffPtr, huart->RxXferCount);

    if (bytes_read > 0)
    {
      /* Update buffer pointer and count */
      huart->pRxBuffPtr += bytes_read;
      huart->RxXferCount -= bytes_read;

      /* If all data received, complete the transfer */
      if (huart->RxXferCount == 0U)
      {
        huart->RxState = HAL_UART_STATE_READY;
        huart->RxEventType = HAL_UART_RXEVENT_TC;

        /* Call appropriate callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          huart->RxEventCallback(huart, huart->RxXferSize);
        }
        else
        {
          huart->RxCpltCallback(huart);
        }
#else
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          HAL_UARTEx_RxEventCallback(huart, huart->RxXferSize);
        }
        else
        {
          HAL_UART_RxCpltCallback(huart);
        }
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
      }
    }
    return;
  }

  /* Check if we're in transmit mode */
  if (huart->TxState == HAL_UART_STATE_BUSY_TX)
  {
    /* Transmit complete - update state */
    huart->TxState = HAL_UART_STATE_READY;

    /* Call transmit complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    huart->TxCpltCallback(huart);
#else
    HAL_UART_TxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    return;
  }

  /* Handle error conditions if needed */
  if (huart->ErrorCode != HAL_UART_ERROR_NONE)
  {
    /* Call error callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    huart->ErrorCallback(huart);
#else
    HAL_UART_ErrorCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    return;
  }
}

/**
* @brief  Receives an amount of data in non blocking mode
* @param  huart  Pointer to a UART_HandleTypeDef structure that contains
*                the configuration information for the specified UART module.
* @retval HAL status
*/
static HAL_StatusTypeDef UART_Receive_IT(UART_HandleTypeDef *huart)
{
  /* Check that a Rx process is ongoing */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* In emulation, simulate receiving one byte at a time from stdin */
    uint8_t received_byte;
    int bytes_read = HAL_BE_In(&received_byte, 1);

    if (bytes_read > 0)
    {
      /* Store the received byte */
      *huart->pRxBuffPtr = received_byte;
      huart->pRxBuffPtr += 1U;

      if (--huart->RxXferCount == 0U)
      {
        /* Rx process is completed, restore huart->RxState to Ready */
        huart->RxState = HAL_UART_STATE_READY;

        /* Initialize type of RxEvent to Transfer Complete */
        huart->RxEventType = HAL_UART_RXEVENT_TC;

        /* Check current reception Mode :
           If Reception till IDLE event has been selected : */
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          /* Set reception type to Standard */
          huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;

#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
          /*Call registered Rx Event callback*/
          huart->RxEventCallback(huart, huart->RxXferSize);
#else
          /*Call legacy weak Rx Event callback*/
          HAL_UARTEx_RxEventCallback(huart, huart->RxXferSize);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
        }
        else
        {
          /* Standard reception API called */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
          /*Call registered Rx complete callback*/
          huart->RxCpltCallback(huart);
#else
          /*Call legacy weak Rx complete callback*/
          HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
        }

        return HAL_OK;
      }
      return HAL_OK;
    }
    else
    {
      /* No data available yet */
      return HAL_OK;
    }
  }
  else
  {
    return HAL_BUSY;
  }
}

/**
* @brief  Receives an amount of data in blocking mode.
* @note   When UART parity is not enabled (PCE = 0), and Word Length is configured to 9 bits (M1-M0 = 01),
*         the received data is handled as a set of u16. In this case, Size must indicate the number
*         of u16 available through pData.
* @param  huart Pointer to a UART_HandleTypeDef structure that contains
*               the configuration information for the specified UART module.
* @param  pData Pointer to data buffer (u8 or u16 data elements).
* @param  Size  Amount of data elements (u8 or u16) to be received.
* @param  Timeout Timeout duration
* @retval HAL status
*/
HAL_StatusTypeDef HAL_UART_Receive(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size, uint32_t Timeout)
{
  uint32_t tickstart = 0U;

  /* Check that a Rx process is not already ongoing */
  if (huart->RxState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return  HAL_ERROR;
    }

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->RxState = HAL_UART_STATE_BUSY_RX;
    huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;

    /* Init tickstart for timeout management */
    tickstart = HAL_GetTick();

    huart->RxXferSize = Size;
    huart->RxXferCount = Size;

    /* In emulation, read all data at once from stdin */
    int bytes_read = HAL_BE_In(pData, Size);

    if (bytes_read > 0)
    {
      /* Update buffer pointer and count */
      huart->pRxBuffPtr = pData + bytes_read;
      huart->RxXferCount = Size - bytes_read;

      /* If all data received, complete the transfer */
      if (huart->RxXferCount == 0U)
      {
        huart->RxState = HAL_UART_STATE_READY;
        return HAL_OK;
      }
      else
      {
        /* Partial data received - in emulation we consider this as timeout */
        huart->RxState = HAL_UART_STATE_READY;
        return HAL_TIMEOUT;
      }
    }
    else
    {
      /* No data received */
      huart->RxState = HAL_UART_STATE_READY;
      return HAL_TIMEOUT;
    }
  }
  else
  {
    return HAL_BUSY;
  }
}

/**
* @brief  This function handles UART Communication Timeout. It waits
*         until a flag is no longer in the specified status.
* @param  huart  Pointer to a UART_HandleTypeDef structure that contains
*                the configuration information for the specified UART module.
* @param  Flag specifies the UART flag to check.
* @param  Status The actual Flag status (SET or RESET).
* @param  Tickstart Tick start value
* @param  Timeout Timeout duration
* @retval HAL status
*/
static HAL_StatusTypeDef UART_WaitOnFlagUntilTimeout(UART_HandleTypeDef *huart, uint32_t Flag, FlagStatus Status,
                                                     uint32_t Tickstart, uint32_t Timeout)
{
  /* In emulation, we don't wait for hardware flags */
  /* Check for timeout immediately */
  if (Timeout != HAL_MAX_DELAY)
  {
    if (((HAL_GetTick() - Tickstart) > Timeout) || (Timeout == 0U))
    {
      return HAL_TIMEOUT;
    }
  }

  /* For RXNE flag (receive data ready), simulate data availability */
  if (Flag == UART_FLAG_RXNE && Status == RESET)
  {
    /* In emulation, we assume data is always ready */
    return HAL_OK;
  }

  /* For TXE flag (transmit data empty), simulate ready to transmit */
  if (Flag == UART_FLAG_TXE && Status == RESET)
  {
    /* In emulation, we assume transmitter is always ready */
    return HAL_OK;
  }

  /* For TC flag (transmit complete), simulate completion */
  if (Flag == UART_FLAG_TC && Status == RESET)
  {
    /* In emulation, we assume transmission is always complete */
    return HAL_OK;
  }

  /* Default: return OK to avoid blocking */
  return HAL_OK;
}

/**
* @brief  Sends an amount of data in blocking mode.
* @note   When UART parity is not enabled (PCE = 0), and Word Length is configured to 9 bits (M1-M0 = 01),
*         the sent data is handled as a set of u16. In this case, Size must indicate the number
*         of u16 provided through pData.
* @param  huart Pointer to a UART_HandleTypeDef structure that contains
*               the configuration information for the specified UART module.
* @param  pData Pointer to data buffer (u8 or u16 data elements).
* @param  Size  Amount of data elements (u8 or u16) to be sent
* @param  Timeout Timeout duration
* @retval HAL status
*/
HAL_StatusTypeDef HAL_UART_Transmit(UART_HandleTypeDef *huart, const uint8_t *pData, uint16_t Size, uint32_t Timeout)
{
  uint32_t tickstart = 0U;

  /* Check that a Tx process is not already ongoing */
  if (huart->gState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return  HAL_ERROR;
    }

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->gState = HAL_UART_STATE_BUSY_TX;

    /* Init tickstart for timeout management */
    tickstart = HAL_GetTick();

    huart->TxXferSize = Size;
    huart->TxXferCount = Size;

    /* In emulation, write data to stdout */
    /* Note: In real hardware, this would write to UART data register */
    /* For emulation, we can just consider it successful */

    /* Update state to indicate transmission is complete */
    huart->TxXferCount = 0U;

    /* At end of Tx process, restore huart->gState to Ready */
    huart->gState = HAL_UART_STATE_READY;

    return HAL_OK;
  }
  else
  {
    return HAL_BUSY;
  }
}

